const clientOf = (p) => DB.clients.find((c) => c.id === (p || S).clientId),
  money = (n) => {
    const v = Math.round(+n || 0);
    return (v < 0 ? "−$" : "$") + Math.abs(v).toLocaleString();
  },
  r2 = (n) => Math.round(100 * (+n || 0)) / 100;
function lineAmount(l, doc) {
  return doc && "sov" === doc.mode
    ? r2((+l.scheduled || 0) * ((+l.pct || 0) / 100))
    : r2((+l.qty || 0) * (+l.rate || 0));
}
function docTotal(d) {
  const lines = d.lines || [],
    sub = r2(lines.reduce((a, l) => a + lineAmount(l, d), 0)),
    disc = d.discount
      ? "amt" === d.discount.type
        ? r2(+d.discount.value || 0)
        : r2(sub * ((+d.discount.value || 0) / 100))
      : 0,
    taxable = r2(lines.filter((l) => l.taxable).reduce((a, l) => a + lineAmount(l, d), 0)),
    tax = r2((taxable - (sub ? (disc * taxable) / sub : 0)) * ((+d.taxRate || 0) / 100)),
    ret = "invoice" === d.type ? r2((sub - disc) * ((+d.retainagePct || 0) / 100)) : 0;
  return { sub: sub, disc: disc, tax: tax, ret: ret, total: r2(sub - disc + tax - ret), taxable: taxable };
}
function nextNumber(kind) {
  const k = { estimate: "est", co: "co", invoice: "inv" }[kind];
  DB.company.seq[k] = (DB.company.seq[k] || 0) + 1;
  return `${{ estimate: DB.company.pe, co: DB.company.pc, invoice: DB.company.pi }[kind]}-${appNow().getFullYear()}-${String(DB.company.seq[k]).padStart(3, "0")}`;
}
function invoiceStatus(c, x) {
  if (["draft", "void", "paid"].includes(x.status)) return x.status;
  const paid = c.payments.filter((p) => p.invoiceId === x.id).reduce((a, p) => a + (+p.amount || 0), 0);
  return paid >= docTotal(x).total - 0.005
    ? "paid"
    : x.due && parse(x.due) < parse(today())
      ? "overdue"
      : paid > 0
        ? "partial"
        : "sent";
}
function sovBilled(c, sovId, exceptId) {
  return c.invoices
    .filter((i) => "sov" === i.mode && "void" !== i.status && i.id !== exceptId)
    .flatMap((i) => i.lines)
    .filter((l) => l.sovId === sovId)
    .reduce((a, l) => a + (+l.pct || 0), 0);
}
function clientFin(c) {
  const approvedCO = c.changeOrders
      .filter((x) => "approved" === x.status || "billed" === x.status)
      .reduce((a, x) => a + docTotal(x).total, 0),
    pendingCO = c.changeOrders.filter((x) => "sent" === x.status).reduce((a, x) => a + docTotal(x).total, 0),
    live = c.invoices.filter((x) => "draft" !== x.status && "void" !== x.status),
    invoiced = live.reduce((a, x) => a + docTotal(x).total, 0),
    retReleased = live.filter((x) => x.retainageRelease).reduce((a, x) => a + docTotal(x).total, 0),
    retHeld = Math.max(0, r2(live.reduce((a, x) => a + docTotal(x).ret, 0) - retReleased)),
    paid = c.payments.filter((x) => !x.unapplied).reduce((a, x) => a + (+x.amount || 0), 0),
    credits = r2(c.payments.filter((x) => x.unapplied).reduce((a, x) => a + (+x.amount || 0), 0)),
    revised = (+c.contract || 0) + approvedCO,
    open = live
      .filter((x) => "paid" !== x.status)
      .map((x) => {
        const paidOn = c.payments
            .filter((p) => p.invoiceId === x.id)
            .reduce((a, p) => a + (+p.amount || 0), 0),
          bal = r2(docTotal(x).total - paidOn),
          age = x.due ? dayDiff(x.due, today()) : 0;
        return { x: x, bal: bal, age: age, paidOn: paidOn };
      })
      .filter((o) => o.bal > 0.5),
    outstanding = r2(open.reduce((a, o) => a + o.bal, 0)),
    overdue = r2(open.filter((o) => o.age > 0).reduce((a, o) => a + o.bal, 0)),
    buckets = { current: 0, d30: 0, d60: 0, d90: 0 };
  open.forEach((o) => {
    o.age <= 0
      ? (buckets.current += o.bal)
      : o.age <= 30
        ? (buckets.d30 += o.bal)
        : o.age <= 60
          ? (buckets.d60 += o.bal)
          : (buckets.d90 += o.bal);
  });
  const sovTotal = c.sov.reduce((a, v) => a + (+v.scheduled || 0), 0),
    sovBilledAmt = c.sov.reduce((a, v) => a + ((+v.scheduled || 0) * sovBilled(c, v.id)) / 100, 0);
  return {
    approvedCO: approvedCO,
    pendingCO: pendingCO,
    revised: revised,
    invoiced: invoiced,
    paid: paid,
    credits: credits,
    outstanding: outstanding,
    overdue: overdue,
    open: open,
    remaining: r2(revised - (invoiced - retReleased) - retHeld),
    retHeld: retHeld,
    retReleased: retReleased,
    buckets: buckets,
    sovTotal: sovTotal,
    sovBilledAmt: sovBilledAmt,
    pctBilled: sovTotal ? Math.round((sovBilledAmt / sovTotal) * 100) : 0,
  };
}
