function poTotal(po) {
  const sub = r2((po.lines || []).reduce((a, l) => a + (+l.qty || 0) * (+l.price || 0), 0));
  return {
    sub: sub,
    tax: r2(sub * ((+po.tax || 0) / 100)),
    shipping: +po.shipping || 0,
    total: r2(sub + sub * ((+po.tax || 0) / 100) + (+po.shipping || 0)),
  };
}
function poPaid(po) {
  return DB.txns.filter((t) => (po.matchedTxns || []).includes(t.id)).reduce((a, t) => a - t.amt, 0);
}
function poState(po) {
  const tot = poTotal(po).total,
    paid = poPaid(po),
    flags = [];
  if ("cancelled" === po.status) return { sev: 0, msg: "Cancelled", flags: flags };
  const tol = (DB.company.matchTol || 2) / 100;
  paid > tot * (1 + tol) + 1 &&
    flags.push(`paid ${money(paid)} vs PO ${money(tot)} (+${Math.round(((paid - tot) / tot) * 100)}%)`),
    po.lines.forEach((l) => {
      l.received &&
        Math.abs(l.received - l.qty) > 0.001 &&
        flags.push(`${l.item}: received ${l.received} ${l.unit} vs ${l.qty} ordered`);
    }),
    ["issued", "partial"].includes(po.status) &&
      po.expected &&
      parse(po.expected) < parse(today()) &&
      flags.push(`expected ${fmt(po.expected)}, not received`),
    "received" === po.status &&
      paid < tot * (1 - tol) - 1 &&
      paid > 0 &&
      flags.push(`received but only ${money(paid)} of ${money(tot)} paid`);
  return {
    sev: flags.some((f) => /vs PO|received \d/.test(f)) ? 3 : flags.length ? 2 : 0,
    msg:
      flags[0] ||
      ("draft" === po.status
        ? "Draft"
        : "issued" === po.status
          ? `Issued · expected ${fmt(po.expected)}`
          : "received" === po.status
            ? paid >= tot * (1 - tol) - 1
              ? "Received & paid"
              : "Received"
            : po.status),
    flags: flags,
    paid: paid,
    tot: tot,
  };
}
function poCommitted(p) {
  return DB.pos
    .filter((po) => po.projectId === p.id && ["issued", "partial", "received"].includes(po.status))
    .reduce((a, po) => a + Math.max(0, poTotal(po).total - poPaid(po)), 0);
}
const TRACKS = {
  design: "Design",
  permit: "Permitting",
  procure: "Procurement",
  build: "Construction",
  close: "Closeout",
};
function trackForTrade(trade, name) {
  const n = (name || "").toLowerCase();
  return "close" === trade || /\bpunch\b|closeout|substantial completion/.test(n)
    ? "close"
    : /\b(design|drawing|drawings|layout|schematic|selection|specification|specs?)\b/.test(n) &&
        !/install/.test(n)
      ? "design"
      : /\b(permit|dob|lpc|filing)\b/.test(n) && !/inspection/.test(n)
        ? "permit"
        : /\border\b|procure|lead time/.test(n) && !/install|template/.test(n)
          ? "procure"
          : "build";
}
const siteHours = (p) =>
    (p || S).project.hours || { days: [1, 2, 3, 4, 5], start: "07:30", end: "16:30", lunch: 30 },
  hmToMin = (hm) => {
    const [h, m] = (hm || "0:0").split(":").map(Number);
    return 60 * h + (m || 0);
  },
  siteDayHours = (p) => {
    const h = siteHours(p);
    return r2((hmToMin(h.end) - hmToMin(h.start) - (h.lunch || 0)) / 60);
  };
function normalizeProject(p) {
  return (
    [
      "tasks",
      "materials",
      "inspections",
      "decisions",
      "comms",
      "chat",
      "docs",
      "files",
      "permits",
      "issues",
      "actions",
      "meetings",
      "requests",
      "log",
    ].forEach((k) => {
      Array.isArray(p[k]) || (p[k] = []);
    }),
    (p.budget = p.budget || {}),
    (p.clientId = p.clientId || ""),
    void 0 === p.baseline && (p.baseline = null),
    (p.project = Object.assign(
      {
        out: "",
        scTaskId: null,
        bin: "",
        lpc: "",
        holidays: "",
        today: "",
        matBuf: 1,
        inspBuf: 5,
        decBuf: 3,
        permitBuf: 30,
        userName: "",
        auto: "off",
        tag: "",
        keywords: "",
        contacts: "",
      },
      p.project || {},
    )),
    (p.project.hours = Object.assign(
      { days: [1, 2, 3, 4, 5], start: "07:30", end: "16:30", lunch: 30 },
      p.project.hours || {},
    )),
    p.tasks.forEach((t) => {
      (t.deps = t.deps || []),
        t.origStart || ((t.origStart = t.start), (t.origEnd = t.end)),
        (t.history = t.history || []),
        (t.actualStart = t.actualStart || ""),
        (t.actualEnd = t.actualEnd || ""),
        (t.track && !t.trackAuto) || ((t.track = trackForTrade(t.trade, t.name)), (t.trackAuto = !0));
    }),
    p.materials.forEach((m) =>
      Object.assign(m, {
        po: m.po || "",
        qty: m.qty || "",
        cost: m.cost || "",
        deliverTo: m.deliverTo || "Site",
        when: m.when || "start",
        line: m.line || "",
      }),
    ),
    p
  );
}
