function exportMatsCSV() {
  const rows = [
    [
      "Material",
      "Category",
      "Vendor",
      "PO",
      "Qty",
      "Cost",
      "For task",
      "Task starts",
      "Order by",
      "Need on site",
      "Lead (wd)",
      "Status",
      "ETA",
      "Deliver to",
      "Flag",
      "Notes",
    ],
  ];
  S.materials.forEach((m) => {
    const { needBy: needBy, orderBy: orderBy } = matDates(m),
      t = task(m.taskId);
    rows.push([
      m.name,
      m.cat,
      m.vendor,
      m.po,
      m.qty,
      m.cost,
      t?.name || "",
      t?.start || "",
      orderBy || "",
      needBy || "",
      m.lead,
      m.status,
      m.eta,
      m.deliverTo,
      matState(m).msg,
      m.notes,
    ]);
  });
  const csv = rows.map((r) => r.map((v) => `"${String(v ?? "").replace(/"/g, '""')}"`).join(",")).join("\n"),
    a = document.createElement("a");
  (a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }))),
    (a.download = `${S.project.name.replace(/\W+/g, "_")}_procurement.csv`),
    a.click();
}
