async function lookup() {
  const q = $("#lk-q").value.trim(),
    st = $("#lk-status"),
    res = $("#lk-res");
  if (!q) return void (st.textContent = "Enter a BIN or job number.");
  (st.textContent = "Searching…"), (res.style.display = "none"), (res.innerHTML = "");
  const urls = /^\d{7}$/.test(q)
    ? [
        [
          "DOB NOW job filings",
          `https://data.cityofnewyork.us/resource/w9ak-ipjd.json?bin=${q}&$limit=25&$order=filing_date DESC`,
        ],
        [
          "DOB permits (BIS)",
          `https://data.cityofnewyork.us/resource/ipu4-2q9a.json?bin__=${q}&$limit=25&$order=issuance_date DESC`,
        ],
      ]
    : [
        [
          "DOB NOW job filings",
          `https://data.cityofnewyork.us/resource/w9ak-ipjd.json?job_filing_number=${encodeURIComponent(q)}&$limit=25`,
        ],
        [
          "DOB permits (BIS)",
          `https://data.cityofnewyork.us/resource/ipu4-2q9a.json?job__=${encodeURIComponent(q)}&$limit=25`,
        ],
      ];
  let html = "",
    any = !1,
    blocked = !1;
  for (const [name, url] of urls)
    try {
      const r = await fetch(url);
      if (!r.ok) throw new Error(r.status);
      const data = await r.json();
      data.length
        ? ((any = !0),
          (html +=
            `<div class="r"><b>${name} · ${data.length} record${data.length > 1 ? "s" : ""}</b></div>` +
            data
              .slice(0, 15)
              .map(
                (d) =>
                  `<div class="r"><b>${esc(d.job_filing_number || d.job__ || "")} ${esc(d.job_type || d.job_type_ || "")} · ${esc(d.filing_status || d.job_status_descrp || d.permit_status || "")}</b>${esc(d.work_type || d.work_on_floor || d.permit_type || "")} ${esc(d.house_no || d.house__ || "")} ${esc(d.street_name || "")}<br><span class="muted">${esc((d.filing_date || d.issuance_date || d.approved_date || "").slice(0, 10))}</span> <a href="#" data-import="${esc(JSON.stringify({ p: d.job_filing_number || d.job__ || "", n: (d.job_type || d.permit_type || "DOB filing") + " " + (d.work_type || "") }))}">Add as inspection record</a>${d.expiration_date ? ` · <a href="#" data-importpermit="${esc(JSON.stringify({ p: d.job__ || d.job_filing_number || "", n: (d.permit_type || d.job_type || "DOB permit") + " " + (d.work_type || ""), iss: (d.issuance_date || "").slice(0, 10), exp: (d.expiration_date || "").slice(0, 10) }))}">Add as permit (expires ${esc((d.expiration_date || "").slice(0, 10))})</a>` : ""}</div>`,
              )
              .join("")))
        : (html += `<div class="r"><b>${name}</b><span class="muted">No records for ${esc(q)}.</span></div>`);
    } catch (e) {
      (blocked = !0),
        (html += `<div class="r"><b>${name}</b><span class="muted">Could not reach NYC Open Data from here (${esc(e.message)}). Use the portal links or record results manually.</span></div>`);
    }
  (res.innerHTML = html),
    (res.style.display = "block"),
    (st.textContent = blocked ? "Some sources were blocked by the browser." : any ? "Done." : "No matches.");
}
