      /^\[?(\d{1,2}\/\d{1,2}\/\d{2,4}),? (\d{1,2}:\d{2}(?::\d{2})?\s?(?:AM|PM|am|pm)?)\]?\s?[-–]?\s?([^:]{1,40}):\s([\s\S]*)$/,
    lines = text.split("\n");
