function parseContacts(str) {
  return (str || "")
    .split("\n")
    .map((l) => l.split(",").map((x) => x.trim()))
    .filter((a) => a[1] && a[1].includes("@"))
    .map((a) => ({ name: a[0], email: a[1].toLowerCase(), role: a[2] || "" }));
}
function routeEmail(e) {
  const subj = (e.subject || "").toUpperCase(),
    from = (e.from || "").toLowerCase(),
    body = ((e.subject || "") + " " + (e.body || "")).toLowerCase();
  for (const p of DB.projects)
    if (p.project.tag && subj.includes(`[${p.project.tag}]`))
      return { id: p.id, conf: 1, why: `subject tag [${p.project.tag}]` };
  for (const p of DB.projects)
    if (parseContacts(p.project.contacts).some((c) => from.includes(c.email)))
      return { id: p.id, conf: 0.9, why: "known contact" };
  let best = null,
    bestN = 0;
  for (const p of DB.projects) {
    const n =
      (p.project.keywords || "")
        .split(",")
        .map((k) => k.trim().toLowerCase())
        .filter((k) => k.length > 2)
        .filter((k) => body.includes(k)).length +
      (p.project.name && body.includes(p.project.name.toLowerCase()) ? 2 : 0);
    n > bestN && ((bestN = n), (best = p));
  }
  return best && bestN >= 1
    ? { id: best.id, conf: bestN >= 2 ? 0.8 : 0.6, why: `${bestN} keyword match${bestN > 1 ? "es" : ""}` }
    : null;
}
