function saveClientEditor() {
  const c = DB.clients.find((x) => x.id === clientOpen);
  if (!c) return;
  const kind = editing.kind.slice(7),
    o = editing.collect(),
    id = editing.id,
    upsert = (arr) => {
      const i = arr.findIndex((x) => x.id === o.id);
      i >= 0 ? (arr[i] = Object.assign(arr[i], o)) : arr.push(o);
    };
  if (
    ("client" === kind && Object.assign(c, o),
    "contact" === kind &&
      (o.primary && c.contacts.forEach((x) => (x.primary = !1)),
      upsert(c.contacts),
      o.email &&
        DB.projects
          .filter((p) => p.clientId === c.id)
          .forEach((p) => {
            parseContacts(p.project.contacts).some((x) => x.email === o.email.toLowerCase()) ||
              (p.project.contacts =
                (p.project.contacts ? p.project.contacts + "\n" : "") + `${o.name}, ${o.email}, Client`);
          })),
    "invoice" === kind &&
      (upsert(c.invoices),
      c.activity.push({
        t: nowStamp(),
        by: S.project.userName || "",
        text: `Invoice ${o.number} ${id ? "updated" : "created"} — ${money(o.amount)}, ${o.status}`,
      })),
    "payment" === kind)
  ) {
    upsert(c.payments);
    const inv = c.invoices.find((i) => i.id === o.invoiceId);
    if (inv) {
      c.payments.filter((p) => p.invoiceId === inv.id).reduce((a, p) => a + (+p.amount || 0), 0) >=
        docTotal(inv).total - 0.005 && (inv.status = "paid");
    }
    c.activity.push({
      t: nowStamp(),
      by: S.project.userName || "",
      text: `Payment ${money(o.amount)} received${inv ? ` — ${inv.number}` : ""}`,
    });
  }
  if ("co" === kind) {
    const was = id ? c.changeOrders.find((x) => x.id === id)?.status : null;
    upsert(c.changeOrders),
      was !== o.status &&
        c.activity.push({
          t: nowStamp(),
          by: S.project.userName || "",
          text: `${o.number} ${o.title} → ${o.status} (${money(o.amount)})`,
        });
  }
  "doc" === kind && upsert(c.docs), closeEditor(), save(), render(), toast("Saved");
}
function deleteClientEditing() {
  const c = DB.clients.find((x) => x.id === clientOpen);
  if (!c) return;
  const kind = editing.kind.slice(7),
    id = editing.id;
  if ("client" === kind) {
    if (!appConfirm(`Delete ${c.name}? Projects stay; their client link is cleared.`)) return;
    (DB.clients = DB.clients.filter((x) => x.id !== c.id)),
      DB.projects.forEach((p) => {
        p.clientId === c.id && (p.clientId = "");
      }),
      (clientOpen = null);
  } else {
    const arr = {
        contact: c.contacts,
        invoice: c.invoices,
        payment: c.payments,
        co: c.changeOrders,
        doc: c.docs,
      }[kind],
      i = arr.findIndex((x) => x.id === id);
    i >= 0 && arr.splice(i, 1);
  }
  closeEditor(), save(), render(), toast("Deleted");
}
