const DOC_FLOW = {
  estimate: ["draft", "sent", "approved", "converted"],
  co: ["draft", "sent", "approved", "billed"],
  invoice: ["draft", "sent", "partial", "paid"],
};
function docColl(c, kind) {
  return "estimate" === kind ? c.estimates : "co" === kind ? c.changeOrders : c.invoices;
}
function findDoc(c, kind, id) {
  return docColl(c, kind).find((x) => x.id === id);
}
function newDoc(c, kind, opts = {}) {
  const base = {
    id: uid("co" === kind ? "co" : "invoice" === kind ? "in" : "es"),
    type: kind,
    number: nextNumber(kind),
    title: "",
    date: today(),
    status: "draft",
    projectId:
      finProj ||
      DB.projects.find((p) => p.clientId === c.id && p.id === S.id)?.id ||
      DB.projects.find((p) => p.clientId === c.id)?.id ||
      "",
    lines: [],
    discount: { type: "pct", value: 0 },
    taxRate: 0,
    terms: DB.company.terms || "Net 15",
    memo: "",
    internal: "",
  };
  return (
    "estimate" === kind &&
      ((base.validUntil = iso(addDays(today(), 30))),
      (base.title = "Proposal"),
      opts.template &&
        "simple" !== opts.template &&
        ((base.template = opts.template), (base.terms = "Deposit due at signing; progress invoices net 7"))),
    "co" === kind && ((base.scheduleDays = 0), (base.title = "Change order")),
    "invoice" === kind &&
      ((base.mode = opts.mode || "items"),
      (base.due = iso(addDays(today(), 15))),
      (base.retainagePct = ("sov" === opts.mode && +DB.company.ret) || 0),
      (base.title =
        "sov" === opts.mode
          ? `Progress billing #${c.invoices.filter((i) => "sov" === i.mode).length + 1}`
          : "Invoice"),
      "sov" === opts.mode &&
        ((base.lines = c.sov.map((v) => ({
          id: uid("l"),
          sovId: v.id,
          item: "Contract" === v.source ? v.desc : `${v.source} ${v.desc}`,
          desc: "",
          scheduled: +v.scheduled || 0,
          prevPct: r2(sovBilled(c, v.id)),
          pct: 0,
          taxable: !!v.taxable,
        }))),
        base.lines.some((l) => l.taxable) && (base.taxRate = +DB.company.tax || 0))),
    "invoice" === kind ||
      base.lines.length ||
      base.lines.push({ id: uid("l"), item: "", desc: "", qty: 1, unit: "ls", rate: 0, taxable: !1 }),
    Object.assign(base, opts.fields || {}),
    docMark(base),
    docColl(c, kind).push(base),
    c.activity.push({
      t: nowStamp(),
      by: S.project.userName || "",
      text: `${base.number} created (${kind})`,
    }),
    base
  );
}
