const NONOP_RULES = [
  [/\btransfer\b/i, "transfer"],
  [/epayment|card pmt|card payment|autopay|amex .*pay|visa .*pay|mastercard .*pay|pymt/i, "cc-payment"],
  [/loan pmt|loan payment|sba|principal/i, "loan"],
  [/owner draw|distribution|capital contrib/i, "owner"],
];
function applyRules(t) {
  const d = (t.desc || "").toLowerCase(),
    nr = NONOP_RULES.find(([re]) => re.test(t.desc || ""));
  if (nr && ("uncat" === t.cat || !t.cat))
    return (t.cat = nr[1]), (t.status = "categorized"), (t.actor = "rule"), !0;
  const r = DB.rules.find((r) => d.includes(r.match.toLowerCase()));
  return (
    !!r &&
    // money coming in on a job-cost rule is a vendor credit, never materials
    ((t.cat = +t.amt > 0 && isJobCat(r.cat) ? "refund" : r.cat),
    (t.code = r.code || ""),
    (t.vendor = r.vendor || t.vendor),
    r.projectId && (t.projectId = r.projectId),
    (t.status = "categorized"),
    (t.actor = "rule"),
    (r.hits = (r.hits || 0) + 1),
    !0)
  );
}
function learnRule(t) {
  if (!t.cat || "uncat" === t.cat) return;
  const key = ruleKey(t.desc);
  if (!key) return;
  const ex = DB.rules.find((r) => r.match === key);
  ex
    ? Object.assign(ex, {
        cat: t.cat,
        code: t.code,
        vendor: t.vendor || ex.vendor,
        projectId: ex.projectId === t.projectId ? ex.projectId : "",
      })
    : DB.rules.push({
        id: uid("r"),
        match: key,
        cat: t.cat,
        code: t.code,
        vendor: t.vendor || "",
        projectId: 1 === DB.projects.length ? t.projectId : "",
        hits: 0,
      });
}
function ruleKey(desc) {
  return (desc || "")
    .toLowerCase()
    .replace(
      /\b(zelle to|zelle from|transfer to|transfer from|online payment|bill pay|wire out|wire in|venmo|paypal|epayment|autopay|recurring)\b/g,
      " ",
    )
    .replace(/\b(ach|debit|credit|purchase|pos|sq|tst|payment|check|\d{2,}|#\d+|[*])\b/g, " ")
    .replace(/[^a-z ]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .split(" ")
    .slice(0, 2)
    .join(" ");
}
function txnDup(t) {
  return DB.txns.some(
    (x) =>
      x.date === t.date &&
      Math.abs(x.amt - t.amt) < 0.005 &&
      x.acct === t.acct &&
      (x.desc || "").slice(0, 12).toLowerCase() === (t.desc || "").slice(0, 12).toLowerCase(),
  );
}
function txnState(t) {
  return "reconciled" === t.status
    ? { sev: 0 }
    : "uncat" !== t.cat && t.cat
      ? isJobCat(t.cat) && !t.projectId
        ? { sev: 2, msg: "Job cost with no project" }
        : isJobCat(t.cat) && !t.line && lineOptions(t.projectId).length
          ? { sev: 1, msg: "Not matched to an estimate line" }
          : isJobCat(t.cat) && !t.code
            ? { sev: 1, msg: "No cost code" }
            : { sev: 0 }
      : { sev: 2, msg: "Uncategorized" };
}
