function budgetFromEstimate() {
  const cl = clientOf(),
    est =
      cl &&
      (cl.estimates.find((e) => "converted" === e.status) ||
        cl.estimates.find((e) => "approved" === e.status) ||
        cl.estimates[0]);
  if (!est) return void toast("No estimate on this client to load from");
  const KW = [
      ["demo", "02"],
      ["dispos", "02"],
      ["fram", "03"],
      ["carpentry", "03"],
      ["window", "04"],
      ["exterior", "04"],
      ["scaffold", "04"],
      ["plumb", "05"],
      ["electric", "06"],
      ["insul", "07"],
      ["drywall", "07"],
      ["taping", "07"],
      ["tile", "08"],
      ["waterproof", "08"],
      ["floor", "09"],
      ["millwork", "10"],
      ["counter", "10"],
      ["trim", "11"],
      ["door", "11"],
      ["hardware", "11"],
      ["paint", "12"],
      ["restor", "12"],
      ["fixture", "13"],
      ["applianc", "13"],
      ["glass", "13"],
      ["permit", "14"],
      ["inspect", "14"],
      ["general cond", "01"],
      ["supervis", "01"],
    ],
    useCost = est.lines.some((l) => +l.cost),
    b = {};
  est.lines.forEach((l) => {
    const k = (l.item + " " + l.desc).toLowerCase(),
      code = (KW.find(([w]) => k.includes(w)) || [null, "99"])[1];
    b[code] = (b[code] || 0) + (useCost ? +l.cost || 0 : lineAmount(l, est));
  }),
    (S.budget = Object.fromEntries(Object.entries(b).map(([k, v]) => [k, r2(v)]))),
    log(`Budget loaded from ${est.number} (${Object.keys(b).length} cost codes)`),
    save(),
    render(),
    toast(
      est.lines.some((l) => +l.cost)
        ? "Budget loaded from line costs"
        : "Budget loaded from prices — add budget costs to the estimate lines for a real margin view",
    );
}
