function vendorLead(vendor) {
  const v = (vendor || "").toLowerCase();
  if (!v) return null;
  const obs = DB.projects
    .flatMap((p) =>
      p.materials
        .filter((m) => m.vendor && m.vendor.toLowerCase() === v && m.orderedOn && m.onSiteDate)
        .map((m) => workdays(m.orderedOn, m.onSiteDate) - 1),
    )
    .filter((n) => n >= 0);
  return obs.length
    ? { n: obs.length, avg: Math.round(obs.reduce((a, b) => a + b, 0) / obs.length), max: Math.max(...obs) }
    : null;
}
