function quickAddAction(text) {
  let title = text,
    assignee = "",
    pri = "med",
    due = "";
  title = title
    .replace(/@([\w.-]+)/g, (_, n) => ((assignee = n), ""))
    .replace(
      /!(high|med|medium|low)/i,
      (_, p) => ((pri = p.toLowerCase().startsWith("med") ? "med" : p.toLowerCase()), ""),
    );
  const dm = title.match(
    /\bdue\s+(\d{1,2}\/\d{1,2}(?:\/\d{2,4})?|today|tomorrow|mon|tue|wed|thu|fri|monday|tuesday|wednesday|thursday|friday)\b/i,
  );
  if (dm) {
    const v = dm[1].toLowerCase(),
      td = today();
    if ("today" === v) due = td;
    else if ("tomorrow" === v) due = nextWork(iso(addDays(td, 1)));
    else if (/^\d/.test(v)) due = normDate(v);
    else {
      const idx = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"].indexOf(v.slice(0, 3));
      let d = addDays(td, 1);
      for (; d.getDay() !== idx; ) d = addDays(d, 1);
      due = iso(d);
    }
    title = title.replace(dm[0], "");
  }
  (title = title.replace(/\s{2,}/g, " ").trim()),
    title &&
      (S.actions.push({
        id: uid("a"),
        title: title,
        assignee: assignee,
        due: due,
        priority: pri,
        status: "todo",
        link: null,
        notes: "",
        source: null,
        createdAt: today(),
        completedAt: "",
      }),
      log(`Task added: ${title}${assignee ? ` (${assignee})` : ""}`),
      save(),
      render(),
      toast(`Added${assignee ? ` for ${assignee}` : ""}${due ? ` · due ${fmt(due)}` : ""}`));
}
