function cashForecast() {
  const td = parse(today()),
    weeks = [];
  for (let i = 0; i < 13; i++) {
    const s0 = addDays(td, 7 * i),
      e0 = addDays(td, 7 * i + 6);
    weeks.push({ start: iso(s0), end: iso(e0), inflow: 0, outflow: 0, items: [] });
  }
  const put = (date, amt, label) => {
    const w = weeks.find((x) => date >= x.start && date <= x.end);
    w && (amt > 0 ? (w.inflow += amt) : (w.outflow += -amt), w.items.push([label, amt]));
  };
  DB.clients.forEach((c) =>
    clientFin(c).open.forEach((o) => {
      let d = o.x.due || today();
      parse(d) < td && (d = iso(addDays(td, 7))), put(d, o.bal, `${c.name.split(" ")[0]} ${o.x.number}`);
    }),
  ),
    DB.bills
      .filter((b) => ["submitted", "pm-approved", "approved"].includes(b.status) && !b.txnId && !b.paidAt)
      .forEach((b) => put(b.due >= today() ? b.due : iso(addDays(td, 3)), -billTotal(b), `Bill ${b.vendor}`)),
    DB.pos
      .filter((p) => ["issued", "partial"].includes(p.status))
      .forEach((p) => {
        const open = Math.max(
          0,
          poTotal(p).total -
            poPaid(p) -
            DB.bills
              .filter((b) => b.poId === p.id && !["void", "rejected", "paid", "verified"].includes(b.status))
              .reduce((a, b) => a + billTotal(b), 0),
        );
        open > 0 && put(iso(addDays(parse(p.expected || today()), 14)), -open, `PO ${p.number}`);
      });
  const runs = DB.payroll.filter((r) => r.total),
    avg = runs.length ? runs.slice(-3).reduce((a, r) => a + r.total, 0) / Math.min(3, runs.length) : 0;
  if (avg) {
    let d = addDays(td, 7);
    for (let i = 0; i < 7; i++) put(iso(d), -avg, "Payroll (est.)"), (d = addDays(d, 14));
  }
  const oh = DB.txns.filter(
      (t) =>
        t.amt < 0 &&
        "rule" === t.actor &&
        "oh" === CATEGORIES.find((c) => c.id === t.cat)?.type &&
        dayDiff(t.date, today()) <= 60,
    ),
    byRule = {};
  oh.forEach((t) => {
    const k = (t.vendor || t.desc).slice(0, 12);
    byRule[k] || (byRule[k] = t);
  }),
    Object.values(byRule).forEach((t) => {
      for (let m = 1; m <= 3; m++) {
        const d = addDays(parse(t.date), 30 * m);
        d >= td && put(iso(d), t.amt, `${t.vendor || t.desc.slice(0, 14)} (recurring)`);
      }
    });
  try {
    billingSuggestions().forEach((s) =>
      put(iso(addDays(td, 21)), s.amount, `Next bill: ${s.p.project.name}`),
    ),
      ("function" == typeof ownedProps ? ownedProps() : []).forEach((p) => {
        const F = propertyFin(p);
        for (let i = 1; i <= 3; i++) {
          const d = new Date(td);
          d.setMonth(d.getMonth() + i),
            d.setDate(3),
            put(iso(d), F.RR.scheduled, `Rent ${p.address}`),
            put(iso(d), -(F.opexM + F.dsM), `Property costs ${p.address}`);
        }
      }),
      DB.projects.forEach((p) => {
        const J = jobFin(p);
        J.retHeld &&
          p.project.target &&
          put(
            p.project.target >= today() ? p.project.target : iso(addDays(td, 60)),
            J.retHeld,
            `Retainage release ${p.project.name}`,
          );
      });
  } catch (e) {}
  const cash = companyBalance().cash + (companyBalance().undeposited || 0);
  let bal = cash;
  return (
    weeks.forEach((w) => {
      (w.net = w.inflow - w.outflow), (bal += w.net), (w.balance = bal);
    }),
    { cash: cash, weeks: weeks, low: Math.min(...weeks.map((w) => w.balance)) }
  );
}
function renderCash() {
  const f = cashForecast(),
    max = Math.max(1, ...f.weeks.map((w) => Math.max(w.inflow, w.outflow)));
  $("#cash-card").innerHTML =
    `<div class="hd"><h3>Cash — next 13 weeks</h3><span class="small muted">bank ${money(f.cash)} today · lowest projected ${money(f.low)}${f.low < 0 ? ' <span style="color:var(--bad);font-weight:600">— goes negative</span>' : ""}</span><span class="grow"></span><span class="small muted">in: open invoices at due date · out: approved bills, open PO balances, payroll cadence, recurring overhead</span></div>\n    <div class="cash">${f.weeks.map((w) => `<div class="wk" title="${esc(w.items.map(([l, a]) => `${l} ${money(a)}`).join("\n"))}"><div class="bar in" style="height:${Math.round((w.inflow / max) * 90)}%"></div><div class="bar out" style="height:${Math.round((w.outflow / max) * 90)}%"></div><div class="lbl">${fmt(w.start)}</div></div>`).join("")}</div>\n    <div class="cashline">${f.weeks.map((w) => `<div class="${w.balance < 0 ? "neg" : ""}"><b>${money(w.balance)}</b>${w.net >= 0 ? "+" : "−"}${money(Math.abs(w.net))}</div>`).join("")}</div>`;
}
