function qtyCheck(what, qty, unit, p) {
  p = p || S;
  const rule = QTY_RULES.find((r) => r.test.test(what || ""));
  if (!rule || !p.takeoff?.rooms?.length) return null;
  const t = takeoffTotals(p),
    est = rule.est(t),
    u = (unit || "").toLowerCase();
  if ("sheets" === rule.unit && !/sheet|ea|pc/.test(u)) return null;
  if ("lf" === rule.unit && !/lf|ft|feet|linear/.test(u)) return null;
  if ("sf" === rule.unit && !/sf|sq/.test(u)) return null;
  if ("gal" === rule.unit && !/gal/.test(u)) return null;
  const prior = (p.requests || [])
      .filter((r) => !["declined"].includes(r.status))
      .flatMap((r) => reqItems(r))
      .filter((it) => rule.test.test(it.what || ""))
      .reduce((a, it) => a + (+it.qty || 0), 0),
    priorPO = DB.pos
      .filter((po) => po.projectId === p.id && "cancelled" !== po.status)
      .flatMap((po) => po.lines)
      .filter((l) => rule.test.test(l.item || ""))
      .reduce((a, l) => a + (+l.qty || 0), 0),
    already = Math.max(prior, priorPO),
    total = already + (+qty || 0),
    over = total - est,
    pct = est ? Math.round((over / est) * 100) : 0;
  return {
    rule: rule.key,
    est: est,
    already: already,
    total: total,
    over: over,
    pct: pct,
    unit: rule.unit,
    why: rule.why(t),
    level: over > 0.15 * est ? "over" : total < 0.6 * est && 0 === already ? "under" : "ok",
    text:
      over > 0.15 * est
        ? `Plans suggest ~${est} ${rule.unit} for the whole project; ${already} already requested/ordered; with these ${qty} you'd be at ${total} — ${over} (${pct}%) over.`
        : total < 0.6 * est && 0 === already
          ? `Plans suggest ~${est} ${rule.unit} in total; this ${qty} covers about ${Math.round((total / est) * 100)}% — fine for a partial order, just flagging.`
          : `Within plan quantities (~${est} ${rule.unit} total; ${total} with this request).`,
  };
}
