function invFind(q) {
  const norm = (x) =>
      (x || "")
        .toLowerCase()
        .replace(/[^a-z0-9 ]/g, " ")
        .replace(/\s+/g, " ")
        .trim(),
    n = norm(q);
  return (
    (n &&
      (DB.inventory.find((i) => norm(i.name) === n) ||
        DB.inventory.find(
          (i) =>
            norm(i.name).includes(n) ||
            (n.includes(norm(i.name).split(" ")[0]) && norm(i.name).split(" ")[0].length > 3),
        ))) ||
    null
  );
}
function invAvailable(i) {
  const reserved = DB.projects
    .flatMap((p) => p.requests || [])
    .flatMap((r) =>
      reqItems(r).filter(
        (it) => it.invId === i.id && !it.done && !["delivered", "closed", "declined"].includes(r.status),
      ),
    )
    .reduce((a, it) => a + (+it.qty || 0), 0);
  return Math.max(0, (+i.qty || 0) - reserved);
}
function invState(i) {
  const f = [];
  return (
    "consumable" === i.type &&
      null != i.reorder &&
      invAvailable(i) <= i.reorder &&
      f.push({
        lvl: 0 === invAvailable(i) ? "bad" : "warn",
        m:
          0 === invAvailable(i)
            ? "Out of stock"
            : `Low: ${invAvailable(i)} ${i.unit} available (reorder at ${i.reorder})`,
      }),
    "tool" === i.type &&
      i.loc.startsWith("p:") &&
      !DB.projects.find((p) => "p:" + p.id === i.loc) &&
      f.push({ lvl: "warn", m: "Located at a project that no longer exists" }),
    f
  );
}
