    if (editing.id) {
      const i = DB.inventory.find((x) => x.id === editing.id),
        before = { qty: i.qty, loc: i.loc };
      Object.assign(i, o),
        before.loc !== i.loc && audit("inventory", i.id, `moved ${locName(before.loc)} → ${locName(i.loc)}`),
        before.qty !== i.qty && audit("inventory", i.id, `count ${before.qty} → ${i.qty}`);
    } else {
      const i = Object.assign({ id: uid("iv") }, o);
      DB.inventory.push(i), audit("inventory", i.id, "added");
    }
