let repTab = "dash",
  repProj = "",
  repFrom = "",
  repTo = "",
  repClient = "",
  repDef = { ds: "lines", group: "", proj: "", from: "", to: "", q: "" };
const inRange = (dt) => (!repFrom || (dt || "") >= repFrom) && (!repTo || (dt || "") <= repTo),
  laborRate = (emp) => (emp ? (+emp.rate || 0) * (1 + (+emp.burden || 0) / 100) : 0);
// Labor by person for a job: hours at the burdened rate, trued up to the actual burden of the payroll run
// that paid (or a close accrued) those days, as jobFin costs them (the Pack read $5,790 at the standard
// burden while the P&L carried $5,667 from the run).
function projectLabor(p) {
  const rows = {},
    tu = payrollTrueUp();
  DB.time
    .filter((e) => e.projectId === p.id && "rejected" !== e.status && inRange(e.date))
    .forEach((e) => {
      const emp = DB.employees.find((x) => x.id === e.empId),
        h = hoursOf(e),
        c = h * laborRate(emp) * tu(e, emp),
        r = (rows[e.empId] = rows[e.empId] || { emp: emp?.name || e.empId, hours: 0, cost: 0, byCode: {} });
      (r.hours += h), (r.cost += c);
      const code = e.code || "99";
      r.byCode[code] = (r.byCode[code] || 0) + c;
    });
  const list = Object.values(rows);
  return {
    list: list,
    hours: r2(list.reduce((a, r) => a + r.hours, 0)),
    cost: r2(list.reduce((a, r) => a + r.cost, 0)),
    byCode: list.reduce(
      (a, r) => (Object.entries(r.byCode).forEach(([c, v]) => (a[c] = (a[c] || 0) + v)), a),
      {},
    ),
  };
}
function projectProfit(p) {
  const J = jobFin(p, [repFrom || "", repTo || today()]),
    c = J.c,
    keys = [];
  c &&
    (c.estimates
      .filter((e) => ["approved", "converted"].includes(e.status) && (!e.projectId || e.projectId === p.id))
      .forEach((e) => {
        "construction" === e.template && ctNumber(e),
          e.lines.forEach((l) => keys.push(`estimate:${e.id}:${l.id}`));
      }),
    c.changeOrders
      .filter((x) => ["approved", "billed"].includes(x.status) && (!x.projectId || x.projectId === p.id))
      .forEach((x) => x.lines.forEach((l) => keys.push(`co:${x.id}:${l.id}`))));
  const lines = keys.map(lineFin).filter(Boolean),
    labor = { list: J.laborByEmp, hours: J.hours, cost: J.laborCost };
  return {
    p: p,
    c: c,
    J: J,
    lines: lines,
    contract: J.contract,
    budget: J.budget,
    committed: J.committed,
    direct: J.billsAmt,
    unlinked: J.txnAmt,
    accrued: J.accrued,
    labor: labor,
    actual: J.actual,
    projCost: J.eac,
    margin: J.estGP,
    marginPct: Math.round(J.estGPPct),
    plannedMargin: J.plannedGP,
    billedGross: J.billed,
    invoicedNet: r2(J.billed + J.taxBilled - J.retHeld),
    retHeld: J.retHeld,
    collected: J.collected,
    outstanding: J.outstanding,
    earned: J.earned,
    overUnder: J.overUnder,
    pctComplete: J.pct,
    backlog: J.backlog,
    invs: J.invs,
    pays: J.pays,
    defs: J.defs,
    byCode: J.byCode.map((b) => ({ ...b, actual: r2(b.bills + b.bank) })),
  };
}
