    net = r2(gross - ohT),
    payroll = r2(DB.payroll.filter((p) => within(p.payDate, range)).reduce((a, p) => a + (+p.total || 0), 0)),
    payrollOH = r2(oh["Payroll — office & overhead"] || 0);
