let homeEdit = !1;
const KPI_RANGES = {
    tm: "This month",
    lm: "Last month",
    tq: "This quarter",
    lq: "Last quarter",
    ty: "This year",
    ly: "Last year",
    l30: "Last 30 days",
    l90: "Last 90 days",
    all: "All time",
  },
  KPI_COMPARE = { prev: "Previous period", yoy: "Same period last year", none: "No comparison" };
function kpiRange(key) {
  const t = today(),
    d = new Date(t + "T00:00:00"),
    y = d.getFullYear(),
    m = d.getMonth(),
    S = (yy, mm, dd = 1) => {
      const x = new Date(yy, mm, dd);
      return iso(x);
    },
    E = (yy, mm) => iso(new Date(yy, mm + 1, 0));
  switch (key) {
    case "tm":
      return [S(y, m), t];
    case "lm":
      return [S(y, m - 1), E(y, m - 1)];
    case "tq":
      return [S(y, 3 * Math.floor(m / 3)), t];
    case "lq": {
      const q = 3 * Math.floor(m / 3) - 3;
      return [S(y, q), E(y, q + 2)];
    }
    case "ty":
      return [`${y}-01-01`, t];
    case "ly":
      return [y - 1 + "-01-01", y - 1 + "-12-31"];
    case "l30":
      return [iso(addDays(t, -29)), t];
    case "l90":
      return [iso(addDays(t, -89)), t];
    default:
      return ["", t];
  }
}
function kpiCompareRange(key, cmp) {
  if ("none" === cmp || "all" === key) return null;
  if ("prev" === cmp) {
    const full = { tm: "lm", tq: "lq", ty: "ly" }[key];
    if (full) return kpiRange(full);
    const t = new Date(today() + "T00:00:00"),
      S = (yy, mm) => iso(new Date(yy, mm, 1)),
      E = (yy, mm) => iso(new Date(yy, mm + 1, 0)),
      y = t.getFullYear(),
      m = t.getMonth();
    if ("lm" === key) return [S(y, m - 2), E(y, m - 2)];
    if ("lq" === key) {
      const q = 3 * Math.floor(m / 3) - 6;
      return [S(y, q), E(y, q + 2)];
    }
    if ("ly" === key) return [y - 2 + "-01-01", y - 2 + "-12-31"];
  }
  const [a, b] = kpiRange(key);
  if ("yoy" === cmp) {
    const s = (x) => {
      const d = new Date(x + "T00:00:00");
      return d.setFullYear(d.getFullYear() - 1), iso(d);
    };
    return [s(a), s(b)];
  }
  const da = new Date(a + "T00:00:00"),
    db = new Date(b + "T00:00:00"),
    len = Math.round((db - da) / 864e5) + 1,
    pb = new Date(da);
  pb.setDate(da.getDate() - 1);
  const pa = new Date(pb);
  return pa.setDate(pb.getDate() - len + 1), [iso(pa), iso(pb)];
}
