    `<div class="tw"><table class="t rep-t" id="ss-table"><thead><tr>${R.cols.map((k) => `<th class="${sums.includes(k) || "count" === k ? "money" : ""}">${k}${s.group && s.summary?.[k] ? ` <span class="small muted">${SUMMARY_TYPES[s.summary[k]]}</span>` : ""}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr ${searchHighlight(s, r)}>${R.cols.map((k) => `<td class="${sums.includes(k) || "count" === k ? "money" : ""}">${fmtv(k, r[k])}</td>`).join("")}</tr>`).join("") || `<tr><td colspan="${Math.max(1, R.cols.length)}" class="muted">No rows match.</td></tr>`}${rows.length ? `<tr style="font-weight:600">${R.cols.map((k, i) => `<td class="${sums.includes(k) ? "money" : ""}">${0 === i ? `Total · ${R.rows.length}` : sums.includes(k) ? fmtv(k, tot[k]) : ""}</td>`).join("")}</tr>` : ""}</tbody></table></div>`
