reminders = function () {
  const out = remindersBase2();
  return (
    ownedProps().forEach((p) => {
      const F = propertyFin(p),
        go = { view: "mbownp", ws: "mb", own: p.id },
        a = p.address;
      F.RR.vacant.length &&
        out.push({
          n: F.RR.vacant.length,
          label: `vacant unit${F.RR.vacant.length > 1 ? "s" : ""} at ${a} · ${money(F.vacancyM)}/mo`,
          go: go,
          sev: "warn",
        }),
        F.delinquent.length &&
          out.push({
            n: F.delinquent.length,
            label: `rent not received this month at ${a} · ${money(F.delinquent.reduce((s, x) => s + x.rent, 0))}`,
            go: go,
            sev: "bad",
          }),
        F.RR.units
          .filter((x) => null != x.daysToEnd && x.daysToEnd <= 90)
          .forEach((x) =>
            out.push({
              n: x.daysToEnd,
              label: `days until ${x.u.name} lease ends at ${a} (${esc(x.L.tenant)})`,
              go: go,
              sev: "warn",
            }),
          ),
        null != F.dscr &&
          F.dscr < 1.2 &&
          out.push({ n: F.dscr, label: `DSCR below 1.20 at ${a}`, go: go, sev: "bad" }),
        null != F.loanDays &&
          F.loanDays < 365 &&
          out.push({
            n: Math.round(F.loanDays / 30),
            label: `months to loan maturity at ${a}`,
            go: go,
            sev: "warn",
          }),
        null != F.htcDays &&
          F.htcDays < 365 &&
          out.push({
            n: Math.round(F.htcDays / 30),
            label: `months left in HTC compliance period at ${a}`,
            go: go,
            sev: "warn",
          });
    }),
    out
  );
};
