const renderMBPropBase = renderMBProp;
function eventRows() {
  const out = [],
    jobName = (id) => DB.projects.find((p) => p.id === id)?.project.name || "",
    jobEnt = (id) => {
      const p = DB.projects.find((x) => x.id === id);
      return p ? entName(entityOfProject(p)) : "";
    },
    propOf = (id) => {
      const p = DB.projects.find((x) => x.id === id);
      return (p?.propertyId && DB.properties.find((x) => x.id === p.propertyId)?.address) || "";
    },
    push = (o) =>
      out.push(
        Object.assign(
          {
            period: (o.date || "").slice(0, 7),
            entity: "",
            job: "",
            code: "",
            property: "",
            unit: "",
            vendor: "",
            customer: "",
            ref: "",
            memo: "",
          },
          o,
        ),
      );
  return (
    DB.clients.forEach((c) => {
      c.invoices
        .filter((i) => !["void", "draft"].includes(i.status))
        .forEach((i) => {
          i.lines.forEach((l) =>
            push({
              date: i.date,
              kind: i.retainerOf ? "Retainer" : l.retainerLine ? "Retainer applied" : "Invoice line",
              side: "Revenue",
              entity: jobEnt(i.projectId) || entName("ent1"),
              job: jobName(i.projectId),
              code:
                ("sov" === i.mode
                  ? c.sov.find((v) => v.id === l.sovId)?.lineRef &&
                    findLine(c.sov.find((v) => v.id === l.sovId).lineRef)?.line.code
                  : l.fromLine && findLine(l.fromLine)?.line.code) || "",
              property: propOf(i.projectId),
              customer: c.name,
              ref: i.number,
              memo: l.item || l.desc || "",
              amount: lineAmount(l, i),
            }),
          );
          const t = docTotal(i);
          t.ret &&
            push({
              date: i.date,
              kind: "Retainage withheld",
              side: "Revenue",
              entity: jobEnt(i.projectId),
              job: jobName(i.projectId),
              customer: c.name,
              ref: i.number,
              amount: -t.ret,
            });
        }),
        c.payments.forEach((py) => {
          const inv = c.invoices.find((i) => i.id === py.invoiceId);
          push({
            date: py.date,
            kind: py.unapplied ? "Credit on account" : "Payment",
            side: "Cash in",
            entity: jobEnt(inv?.projectId) || entName("ent1"),
            job: jobName(inv?.projectId),
            property: propOf(inv?.projectId),
            customer: c.name,
            ref: inv?.number || "",
            memo: py.ref || py.method || "",
            amount: +py.amount || 0,
          });
        });
    }),
    DB.bills
      .filter((b) => BILL_COSTED.includes(b.status))
      .forEach((b) =>
        (b.lines || []).forEach((l) =>
          push({
            date: b.date,
            kind: b.ic ? "Intercompany bill" : "Bill line",
            side: "Cost",
            entity: entName(b.entityId || "ent1"),
            job: jobName(b.projectId),
            code: b.code || "",
            property: propOf(b.projectId),
            vendor: b.vendor,
            ref: b.number,
            memo: l.desc || "",
            amount: +l.amount || 0,
          }),
        ),
      ),
    DB.txns
      .filter((t) => t.amt < 0 && !txnViaBill(t, DB.bills))
      .forEach((t) =>
        push({
          date: t.date,
          kind: "Bank",
          side: isJobCat(t.cat) ? "Cost" : "Overhead",
          entity: entName(("function" == typeof entityOfTxn ? entityOfTxn(t) : null) || "ent1"),
          job: jobName(t.projectId),
          code: t.code || "",
          property: propOf(t.projectId),
          vendor: t.vendor || "",
          ref: t.desc || "",
          memo: cfoCatName(t.cat),
          amount: -t.amt,
        }),
      ),
    DB.time
      .filter((e) => "rejected" !== e.status && !e.icBillId)
      .forEach((e) => {
        const emp = DB.employees.find((x) => x.id === e.empId);
        push({
          date: e.date,
          kind: "Labor (clocked)",
          side: "Cost",
          entity: entName(emp?.entityId || "ent1"),
          job: jobName(e.projectId),
          code: e.code || "",
          property: propOf(e.projectId),
          vendor: emp?.name || e.empId,
          ref: hoursOf(e) + " h",
          memo: e.notes || "",
          amount: r2(hoursOf(e) * laborRate(emp)),
        });
      }),
    DB.payroll
      .filter((r) => ["paid", "verified"].includes(r.status))
      .forEach((r) =>
        push({
          date: r.payDate,
          kind: "Payroll",
          side: "Cost",
          entity: entName(r.entityId || "ent1"),
          ref: r.period,
          memo: `${r.employees} employees`,
          amount: +r.total || 0,
        }),
      ),
    ("function" == typeof ownedProps ? ownedProps() : []).forEach((p) => {
      const en = propEntity(p)?.name || "";
      (p.owned.rentLedger || [])
        .filter((r) => r.paid)
        .forEach((r) =>
          push({
            date: r.date || r.month + "-01",
            kind: "Rent",
            side: "Revenue",
            entity: en,
            property: p.address,
            unit: p.owned.units.find((u) => u.id === r.unitId)?.name || "",
            customer: p.owned.units.find((u) => u.id === r.unitId)?.lease?.tenant || "",
            ref: r.month,
            amount: +r.amount || 0,
          }),
        );
    }),
    out.sort((a, b) => (b.date || "").localeCompare(a.date || ""))
  );
}
function lineCompletePct(c, v) {
  if (!v.lineRef) return null;
  const f = lineFin(v.lineRef);
  if (!f) return null;
  const budget = f.budget || 0;
  return budget ? Math.min(100, Math.round((f.actual / budget) * 100)) : null;
}
function progressPrefill(c, inv, pctJob) {
  inv.lines.forEach((l) => {
    const v = c.sov.find((x) => x.id === l.sovId),
      done = v ? lineCompletePct(c, v) : null,
      target = null != done ? done : Math.round(100 * pctJob);
    (l.pct = Math.max(0, r2(target - (+l.prevPct || 0)))), (l.suggested = !0);
  }),
    (inv.title = `Progress billing — work through ${fmtL(today())}`),
    (inv.memo =
      (inv.memo ? inv.memo + "\n" : "") +
      "Percentages pre-filled from cost to date against each line's budget. Adjust before sending.");
}
