    emp = DB.employees.find((e) => e.id === u?.employeeId);
  if (!emp) return toast("Sign in as a designer to log hours"), null;
  date = date || today();
  let start =
    9 + DB.time.filter((t) => t.empId === emp.id && t.date === date).reduce((a, t) => a + hoursOf(t), 0);
  start + hours > 23.75 && (start = Math.max(0, Math.min(start, 23.75 - hours)));
