async function intakeRun(m, text) {
  const p = DB.projects.find((x) => x.id === m.projectId),
    rooms = roomsOf(p.id).map((r) => r.name),
    prompt = `You are the design studio's meeting assistant. From this meeting transcript, extract JSON only: {"items":[{"kind":"decision|question|promise|pref|ffe|site","text":"…","room":"one of: ${rooms.join(", ")} or empty","owner":"person","dir":"us|client (promises only)","due":"YYYY-MM-DD or empty","gate":"what it blocks, or empty","hours":number or 0}]}. Decisions = what the client agreed; questions = still open; promises = who owes what; pref = likes/dislikes/rules; ffe = product or material selections; site = measurements, existing conditions, things to check on site. Be faithful, no invention, ≤45 items.\n\nTRANSCRIPT:\n${text.slice(0, 6e4)}`,
    r = await ai(prompt, 4e3);
  if (r.startsWith("__ERR")) return { error: r.slice(6, 120) };
  const j = safeJSON(r);
  if (!j || !j.items) return { error: "could not read the reply" };
  const items = j.items
    .map((it) => ({
      id: uid("ik"),
      kind: INTAKE_KINDS[it.kind] ? it.kind : "site",
      text: String(it.text || "").trim(),
      room: roomsOf(p.id).find((r) => r.name.toLowerCase() === String(it.room || "").toLowerCase())?.id || "",
      owner: it.owner || "",
      dir: it.dir || "",
      due: it.due || "",
      gate: it.gate || "",
      hours: +it.hours || 0,
      status: "proposed",
    }))
    .filter((x) => x.text);
  return (
    (DB.studio.intake[m.id] = { meetingId: m.id, at: today(), by: "assistant", items: items }),
    (m.intake = "proposed"),
    save(),
    { n: items.length }
  );
}
