    [...P.rules, ...P.dislikes].forEach((x) => {
      const words = x
        .toLowerCase()
        .replace(/^no\s+|^never\s+/, "")
        .split(/[^a-z0-9]+/)
        .filter(
          (w) =>
            w.length > 3 &&
            ![
              "only",
              "look",
              "things",
              "behind",
              "doors",
              "with",
              "that",
              "very",
              "hard",
              "convince",
            ].includes(w),
        );
      words.length && words.every((w) => t.includes(w)) && hits.push(x);
    }),
    [...new Set(hits)]
