function ptPhaseBurn() {
  const rows = [];
  return (
    studioProjects().forEach((p) => {
      const rooms = roomsOf(p.id),
        prog = {
          sd: rooms.length
            ? Math.round((rooms.filter((r) => "sd" !== r.phase).length / rooms.length) * 100)
            : null,
          dd: rooms.length
            ? Math.round((rooms.filter((r) => ["cd", "done"].includes(r.phase)).length / rooms.length) * 100)
            : null,
          cd: rooms.length
            ? Math.round((rooms.filter((r) => "done" === r.phase).length / rooms.length) * 100)
            : null,
        };
      phaseHours(p).forEach((x) => {
        if (!x.est) return;
        const burn = Math.round((x.used / x.est) * 100),
          k = /schematic|concept/i.test(x.line.item)
            ? "sd"
            : /development/i.test(x.line.item)
              ? "dd"
              : /construction doc/i.test(x.line.item)
                ? "cd"
                : null,
          pr = k ? prog[k] : null;
        (burn || pr) && rows.push({ p: p, x: x, burn: burn, pr: pr });
      });
    }),
    rows.sort((a, b) => b.burn - (b.pr ?? b.burn) - (a.burn - (a.pr ?? a.burn))),
    `<div class="dx-pb">${
      rows
        .slice(0, 8)
        .map(
          (r) =>
            `<div class="${r.burn > 100 || (null != r.pr && r.burn > r.pr + 20) ? "bad" : null != r.pr && r.burn > r.pr + 10 ? "warn" : ""}"><span><b>${esc(shortName(r.p))}</b> · ${esc(phaseShort(r.x.line.item))}</span><div class="pair"><div class="bar"><i style="width:${Math.min(100, r.burn)}%"></i></div><em>${r.burn}% of hours</em></div>${null != r.pr ? `<div class="pair"><div class="bar"><i class="p" style="width:${r.pr}%"></i></div><em>${r.pr}% of rooms through</em></div>` : ""}</div>`,
        )
        .join("") || '<div class="muted small">No phases in progress.</div>'
    }</div><div class="small muted">Hours burned vs rooms moved past the phase. Red when burn leads progress by 20 points — the leak is in that phase, not the project.</div>`
  );
}
function ptRealization() {
  const emps = DB.employees.filter(isDesignStaff).map((e) => e.id),
    rows = studioProjects().map((p) => {
      const c = DB.clients.find((x) => x.id === p.clientId),
        est = designEst(p),
        hrs = DB.time
          .filter((t) => t.projectId === p.id && emps.includes(t.empId))
          .reduce((a, t) => a + hoursOf(t), 0),
        fees = c && est ? designBilled(c, est) : 0,
        rate = studioRate(p),
        eff = hrs ? r2(fees / hrs) : 0,
        real = hrs ? Math.round((fees / (hrs * rate)) * 100) : 0;
      return { p: p, hrs: r2(hrs), fees: fees, rate: rate, eff: eff, real: real };
    }),
    H = rows.reduce((a, r) => a + r.hrs, 0),
    F = rows.reduce((a, r) => a + r.fees, 0),
    rate = rows[0]?.rate || designRate(),
    eff = H ? r2(F / H) : 0;
  return `<div class="dx-tiles">${tile(H ? Math.round((F / (H * rate)) * 100) + "%" : "—", "Studio Realization · Fees ÷ (Hours × Bill Rate)", H && F / (H * rate) < 0.75 ? "bad" : H && F / (H * rate) < 0.85 ? "warn" : "ok")}${tile(money(eff) + "/hr", `Effective Rate vs $${rate} Bill Rate`, eff < 0.65 * rate ? "bad" : eff < 0.8 * rate ? "warn" : "ok")}</div><table class="t dash-t"><thead><tr><th>Project</th><th class="money">Hours</th><th class="money">Fees billed</th><th class="money">Eff. rate</th><th class="money">Real.</th></tr></thead><tbody>${rows.map((r) => `<tr><td><b>${esc(shortName(r.p))}</b></td><td class="money">${r.hrs}</td><td class="money">${money(r.fees)}</td><td class="money">${money(r.eff)}</td><td class="money ${r.real < 75 ? "bad" : r.real < 85 ? "warn" : ""}">${r.real}%</td></tr>`).join("")}</tbody></table><div class="small muted">This is the CEO's studio number: it turns hours into whether the studio covers its burden. Billing lag shows here first — bill banked hours and it recovers.</div>`;
}
const FILING_TYPICAL = { lpc: 45, altco: 30, alt2: 25, demo: 20, frame: 20 };
function ptFilingsX() {
  const td = today(),
    rows = DB.studio.filings
      .filter((f) => "approved" !== f.status && "not-started" !== f.status)
      .map((f) => {
        const p = DB.projects.find((x) => x.id === f.projectId),
          days = f.submittedOn ? dayDiff(f.submittedOn, td) : f.startedOn ? dayDiff(f.startedOn, td) : 0,
          typ = FILING_TYPICAL[f.key] || 30,
          court = "submitted" === f.status ? "agency" : "us";
        return { f: f, p: p, days: days, typ: typ, court: court, ratio: days / typ };
      })
      .sort((a, b) => b.ratio - a.ratio),
    unbilled = DB.studio.filings.filter(
      (f) =>
        ("not-started" !== f.status && !f.billed.start) ||
        (["submitted", "objections", "approved"].includes(f.status) && !f.billed.submit) ||
        ("approved" === f.status && !f.billed.approve),
    );
  return `${dashList(
    rows.map(
      (r) =>
        `<div class="rem-row ${r.ratio > 1.5 || ("us" === r.court && r.days > 5) ? "bad" : r.ratio > 1 ? "warn" : ""}" data-remgo='${esc(JSON.stringify({ view: "sfile", project: r.p.id }))}'><b>${r.days}d</b><span><b>${esc(r.f.name)}</b> · ${esc(shortName(r.p))} · <span class="pill ${FILING_STATUS[r.f.status][1]}">${FILING_STATUS[r.f.status][0]}</span> · ball with <b>${r.court}</b> · typical ${r.typ}d${r.f.rounds ? ` · round ${r.f.rounds}` : ""}<div class="dx-bullet"><i style="width:${Math.min(100, 50 * r.ratio)}%" class="${r.ratio > 1 ? "bad" : "ok"}"></i><u style="left:50%"></u></div></span></div>`,
    ),
    "No filings in review.",
  )}${unbilled.length ? `<div class="small warn" style="margin-top:6px">${unbilled.length} filing milestone${1 === unbilled.length ? "" : "s"} reached and not invoiced — see Billable now.</div>` : ""}<div class="small muted">Days vs our typical for that agency (LPC staff-level ≈45, DOB plan exam ≈25). Red past 1.5× typical, or in our court more than 5 days.</div>`;
}
function ptDecisionLat() {
  const td = today(),
    open = [],
    lat = {};
  DB.projects.forEach((p) => {
    const c = DB.clients.find((x) => x.id === p.clientId);
    p.decisions.forEach((d) => {
      if ("made" === d.status && d.madeOn && d.date) {
        const k = c?.name || "—";
        (lat[k] = lat[k] || []).push(dayDiff(d.date, d.madeOn));
      }
      if ("open" === d.status) {
        const due = d.due || decDue(d);
        open.push({
          p: p,
          c: c,
          d: d,
          due: due,
          days: d.date ? dayDiff(d.date, td) : null,
          gate: due ? dayDiff(td, due) : null,
        });
      }
    });
  });
  return (
    open.sort((a, b) => (a.gate ?? 99) - (b.gate ?? 99)),
    `${dashList(
      open.slice(0, 8).map((o) => {
        const m =
            o.c && lat[o.c.name]
              ? ((a) => {
                  const s = a.slice().sort((x, y) => x - y);
                  return s.length ? s[Math.floor(s.length / 2)] : null;
                })(lat[o.c.name])
              : null,
          cls =
            (null != o.gate && o.gate <= 5) || (null != o.days && o.days > 14)
              ? "bad"
              : (null != o.gate && o.gate <= 10) || (null != o.days && o.days > 7)
                ? "warn"
                : "";
        return dashItem(
          null == o.gate ? "—" : o.gate < 0 ? "late" : o.gate + "d",
          `${esc(shortName(o.p))} · ${esc(o.d.name)}${o.d.gate ? ` <span class="pill warn">gate · ${esc(o.d.gate)}</span>` : ""} · ${esc(o.d.owner || "")}${null != o.days ? ` · open ${o.days}d` : ""}${null != m ? ` · this client usually takes ${m}d` : ""}`,
          { view: "dec", project: o.p.id },
          cls,
        );
      }),
      "Nothing open.",
    )}<div class="small muted">Days to the gate the decision holds, next to how long this client usually takes. The evidence for the "we need this by Friday" conversation.</div>`
  );
}
function ptDeliverables() {
  const td = today(),
    emps = new Set(DB.employees.map((e) => e.name)),
    rows = [];
  return (
    studioProjects().forEach((p) => {
      p.tasks
        .filter(
          (t) => "done" !== t.status && "design" === (t.track || "") && t.end && dayDiff(td, t.end) <= 14,
        )
        .forEach((t) =>
          rows.push({
            p: p,
            d: t.end,
            who: t.assignee || "",
            text: t.name,
            ext: t.assignee && !emps.has(t.assignee),
            stale: !1,
          }),
        ),
        DB.studio.meetings
          .filter((m) => m.projectId === p.id && "proposed" === m.intake)
          .forEach((m) =>
            rows.push({
              p: p,
              d: m.date,
              who: "you",
              text: `Confirm ${DB.studio.intake[m.id]?.items.filter((i) => "proposed" === i.status).length || 0} proposals · ${m.title}`,
              ext: !1,
            }),
          );
    }),
    DB.studio.promises
      .filter((x) => "open" === x.status && "us" === x.dir && x.due && dayDiff(td, x.due) <= 14)
      .forEach((x) =>
        rows.push({
          p: DB.projects.find((p) => p.id === x.projectId),
          d: x.due,
          who: x.owner || "",
          text: x.text,
          ext: !1,
        }),
      ),
    rows.sort((a, b) => (a.d || "").localeCompare(b.d || "")),
    dashList(
      rows
        .slice(0, 10)
        .map(
          (r) =>
            `<div class="rem-row ${dayDiff(td, r.d) < 0 ? "bad" : dayDiff(td, r.d) <= 3 ? "warn" : ""}" data-remgo='${esc(JSON.stringify({ view: "sboard", project: r.p?.id }))}'><b>${fmt(r.d)}</b><span><span class="muted">${esc(shortName(r.p || { project: { name: "" } }))} · ${r.ext ? '<span class="pill info">consultant</span> ' : ""}${esc(r.who)} · </span>${esc(r.text)}</span></div>`,
        ),
      "Nothing due in the next 14 days.",
    )
  );
}
function ptHoursPeople() {
  const td = today(),
    mon = iso(addDays(td, -(parse(td).getDay() + 6) % 7)),
    days = [];
  for (let i = 1; days.length < 10; i++) {
    const d = iso(addDays(td, -i));
    [0, 6].includes(parse(d).getDay()) || days.push(d);
  }
  return `<div class="dx-people">${DB.employees
    .filter(isDesignStaff)
    .map((e) => {
      const wk = DB.time.filter((t) => t.empId === e.id && t.date >= mon && t.date <= td),
        h = r2(wk.reduce((a, t) => a + hoursOf(t), 0)),
        bill = r2(wk.filter((t) => t.projectId).reduce((a, t) => a + hoursOf(t), 0)),
        un = days.filter((d) => !DB.time.some((t) => t.empId === e.id && t.date === d)).length;
      return { e: e, h: h, bill: bill, un: un, util: Math.round((h / 40) * 100) };
    })
    .map(
      (r) =>
        `<div class="${r.un >= 2 || r.util < 55 || r.util > 95 ? "bad" : 1 === r.un || r.util < 65 ? "warn" : ""}"><b>${esc(r.e.name)}</b><div class="bar"><i style="width:${Math.min(100, r.util)}%"></i><i class="b" style="width:${Math.min(100, Math.round((r.bill / 40) * 100))}%"></i></div><span>${r.h} hrs this week · ${r.bill} on projects${r.un ? ` · <em>${r.un} unlogged day${1 === r.un ? "" : "s"}</em>` : ""}</span></div>`,
    )
    .join(
      "",
    )}</div><div class="small muted">Against a 40-hour week; dark = on projects. Unlogged days in the last 10 working days are the realization leak.</div>`;
}
function ptRework() {
  const rows = studioProjects().map((p) => {
    const ch = DB.studio.changes.filter((c) => c.projectId === p.id);
    let re = 0;
    ch.forEach((c) => {
      re += DB.time
        .filter(
          (t) =>
            t.projectId === p.id &&
            t.date >= c.at &&
            dayDiff(c.at, t.date) <= 10 &&
            /re-?draw|revise|rework|update|re-?issue/i.test(t.notes || ""),
        )
        .reduce((a, t) => a + hoursOf(t), 0);
    });
    const total = DB.time.filter((t) => t.projectId === p.id).reduce((a, t) => a + hoursOf(t), 0),
      unv = roomsOf(p.id).filter((r) => 0 === roomProv(r) && "sd" !== r.phase).length;
    return { p: p, re: r2(re), pct: total ? Math.round((re / total) * 100) : 0, ch: ch.length, unv: unv };
  });
  return dashList(
    rows.map((r) =>
      dashItem(
        r.re + " h",
        `${esc(shortName(r.p))} · rework after ${r.ch} dimension change${1 === r.ch ? "" : "s"} · ${r.pct}% of hours${r.unv ? ` · <b class="bad">${r.unv} rooms past SD still unverified</b>` : ""}`,
        { view: "sdraw", project: r.p.id },
        r.unv || r.pct > 8 ? "bad" : r.pct > 4 ? "warn" : "",
      ),
    ),
    "No design projects.",
  );
}
function ptCadence() {
  const td = today(),
    rows = studioProjects().map((p) => {
      const deck = sheetsOf(p.id)
          .filter((s) => "deck" === s.set && s.issuedOn)
          .map((s) => s.issuedOn)
          .sort()
          .pop(),
        mt = DB.studio.meetings
          .filter((m) => m.projectId === p.id)
          .map((m) => m.date)
          .sort()
          .pop(),
        tr = DB.studio.transmittals
          .filter((t) => t.projectId === p.id)
          .map((t) => t.date)
          .sort()
          .pop(),
        touch = [deck, mt].filter(Boolean).sort().pop(),
        dT = touch ? Math.max(0, dayDiff(touch, td)) : null,
        dI = tr ? Math.max(0, dayDiff(tr, td)) : null;
      return { p: p, dT: dT, dI: dI };
    });
  return dashList(
    rows.map((r) =>
      dashItem(
        null == r.dT ? "—" : r.dT + "d",
        `${esc(shortName(r.p))} · since last client touchpoint${null != r.dI ? ` · ${r.dI}d since last set issued` : ""}`,
        { view: "sboard", project: r.p.id },
        null != r.dT && r.dT > 21 ? "bad" : null != r.dT && r.dT > 14 ? "warn" : "",
      ),
    ),
    "No design projects.",
  );
}
function ptFFE() {
  const rows = DB.studio.ffe,
    by = {};
  FFE_STATUS.forEach((s) => (by[s] = rows.filter((f) => f.status === s).length));
  today();
  const late = rows
    .filter((f) => f.materialId)
    .map((f) => {
      const p = DB.projects.find((x) => x.id === f.projectId),
        m = p?.materials.find((x) => x.id === f.materialId);
      return { f: f, p: p, m: m };
    })
    .filter((x) => x.m && !["ordered", "shipped", "on-site"].includes(x.m.status));
  return `<div class="dx-funnel five">${FFE_STATUS.map((s) => `<div><span>${s}</span><b>${by[s]}</b></div>`).join("")}</div>${dashList(
    late
      .slice(0, 5)
      .map((x) =>
        dashItem(
          "approved",
          `${esc(x.f.item)} · ${esc(shortName(x.p))} — not ordered yet`,
          { view: "mat", project: x.p.id },
          "warn",
        ),
      ),
    "Every approved selection is ordered.",
  )}`;
}
