  return `<div class="crumb"><a href="#" data-slback>Pipeline</a><span>›</span>${esc(l.name)}</div><div class="ph"><div><h2 data-ia-keep="1">${esc(l.name)}</h2><div class="lead">${esc(l.addr || "")}${l.buildingType ? " · " + esc(l.buildingType) : ""}${l.scope ? " · " + esc(l.scope) : ""} · ${l.email ? esc(l.email) : ""}${l.email && l.phone ? " · " : ""}${l.phone ? esc(l.phone) : ""}</div></div><div class="acts"><button class="btn sm" data-lead-edit="${l.id}">Edit lead</button></div></div>${stageBar}<div class="sl-grid"><div>${now}${disc}${money_}</div><div>${score}${people}${bldg}${plan}${log}</div></div>`;
