function cpLint(text) {
  const t = text || "",
    hits = CP_BANNED.filter((rx) => rx.test(t)).map((rx) => (t.match(rx) || [""])[0]);
  return (
    /\b(projected|target|expected)\s+(irr|return)|\birr\b|\d+(\.\d+)?%\s*(irr|return)/i.test(t) &&
      !/assum/i.test(t) &&
      hits.push("a projected return without its assumptions"),
    hits
  );
}
