function cpNumbers() {
  const I = DB.investors || [],
    R = DB.raises || [],
    med =
      (today(),
      (a) => {
        const s = a.filter((x) => null != x).sort((x, y) => x - y);
        if (!s.length) return null;
        const m = Math.floor(s.length / 2);
        return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
      }),
    allP = R.flatMap((r) => (r.pipeline || []).map((p) => ({ r: r, p: p, i: cpInv(p.investorId) }))),
    visited = (p, k) => p.stage === k || (p.history || []).some((h) => h.stage === k) || "target" === k,
    ORDER = CP_STAGES.filter((s) => "passed" !== s[0]).map((s) => s[0]),
    funnel = CP_STAGES.filter((s) => "passed" !== s[0])
      .map(([k, n]) => ({
        k: k,
        name: n,
        n: allP.filter((x) => {
          return (
            (p = x.p),
            Math.max(0, ORDER.indexOf(p.stage), ...(p.history || []).map((h) => ORDER.indexOf(h.stage))) >=
              ORDER.indexOf(k)
          );
          var p;
        }).length,
      }))
      .map((s, i, a) => ({ ...s, conv: i && a[i - 1].n ? Math.round((s.n / a[i - 1].n) * 100) : null })),
    funded = allP.filter((x) => "funded" === x.p.stage),
    checks = funded.map((x) => +x.p.amount || 0),
    avg = checks.length ? checks.reduce((a, b) => a + b, 0) / checks.length : 0,
    daysToFund = med(
      funded.map((x) => {
        const t = (x.p.history || []).find((h) => "target" === h.stage || "qualified" === h.stage);
        return t ? cpDays(t.at, x.p.fundedAt || x.p.since) : null;
      }),
    ),
    softToSigned = (() => {
      const s = allP.filter((x) => visited(x.p, "soft")),
        g = s.filter((x) => visited(x.p, "subscribed") || "funded" === x.p.stage);
      return s.length ? Math.round((g.length / s.length) * 100) : null;
    })(),
    firstToCommit = (() => {
      const m = allP.filter((x) => x.i && (x.i.touches || []).length),
        c = m.filter((x) => visited(x.p, "committed"));
      return m.length ? Math.round((c.length / m.length) * 100) : null;
    })(),
    reup = (() => {
      const byInv = {};
      funded.forEach((x) => {
        byInv[x.p.investorId] = (byInv[x.p.investorId] || 0) + 1;
      });
      const n = Object.keys(byInv).length;
      return n ? Math.round((Object.values(byInv).filter((v) => v > 1).length / n) * 100) : null;
    })(),
    bySource = {};
  I.forEach((i) => {
    const k = i.source || "Unknown",
      s = (bySource[k] = bySource[k] || { n: 0, funded: 0, amount: 0, spend: 0 });
    s.n++;
    const f = cpPositions(i).filter((x) => "funded" === x.p.stage);
    f.length && (s.funded++, (s.amount += f.reduce((a, x) => a + (+x.p.amount || 0), 0)));
  }),
    (DB.cpSpend || []).forEach((m) => {
      (bySource[m.source] = bySource[m.source] || { n: 0, funded: 0, amount: 0, spend: 0 }).spend +=
        +m.amount || 0;
    });
  const passedBy = {};
  allP
    .filter((x) => "passed" === x.p.stage)
    .forEach((x) => {
      const k = (CP_LOST.find((c) => c[0] === x.p.lostCode) || ["", x.p.lostCode || "Unsaid"])[1];
      passedBy[k] = (passedBy[k] || 0) + 1;
    });
  const conc = R.map((r) => ({ r: r, S: cpSums(r) })).filter((x) => x.S.soft),
    k1 = R.flatMap((r) => Object.entries(r.k1 || {}).map(([y, k]) => ({ r: r, y: y, k: k }))),
    k1Late = k1.filter((x) => x.k.late).length,
    spend = (DB.cpSpend || []).reduce((a, m) => a + (+m.amount || 0), 0),
    raised = funded.reduce((a, x) => a + (+x.p.amount || 0), 0);
  return {
    funnel: funnel,
    avg: avg,
    med: med(checks),
    daysToFund: daysToFund,
    softToSigned: softToSigned,
    firstToCommit: firstToCommit,
    reup: reup,
    bySource: bySource,
    passedBy: passedBy,
    conc: conc,
    k1Late: k1Late,
    k1N: k1.length,
    spend: spend,
    raised: raised,
    cost: raised ? spend / raised : null,
    nFunded: funded.length,
    nPartners: new Set(funded.map((x) => x.p.investorId)).size,
  };
}
