function hbEndOfMonth(d) {
  const x = new Date(String(d).slice(0, 10) + "T00:00:00");
  return x.setMonth(x.getMonth() + 1, 0), iso(x);
}
const hbStages = () => DB.hub.pipeline.stages,
  hbStage = (id) => hbStages().find((s) => s.id === id) || { id: id, label: id, prob: 0 },
  hbUsers = () =>
    (DB.users || []).filter((u) => !["crew", "driver", "client"].includes(u.role)).map((u) => u.name),
  hbMe = () => (("function" == typeof currentUser && currentUser()) || {}).name || "Owner",
  hbFmtMoney = (v) => (null == v || "" === v ? "" : money(+v || 0)),
  hbFmtDate = (d) => {
    if (!d) return "";
    const s = String(d).slice(0, 10),
      y = s.slice(0, 4);
    return y === String(today()).slice(0, 4) ? fmt(s) : `${fmt(s)}/${y.slice(2)}`;
  },
  hbRel = (d) => {
    if (!d) return "";
    const n = Math.round(
      (new Date(today() + "T00:00:00") - new Date(String(d).slice(0, 10) + "T00:00:00")) / 864e5,
    );
    return 0 === n
      ? "today"
      : 1 === n
        ? "yesterday"
        : n > 1
          ? `${n} days ago`
          : -1 === n
            ? "tomorrow"
            : `in ${-n} days`;
  };
