function hbSeqTick() {
  const td = today();
  (DB.hub.enrollments || [])
    .filter((e) => "active" === e.status)
    .forEach((e) => {
      const s = DB.hub.sequences.find((x) => x.id === e.sequenceId),
        c = DB.hub.contacts.find((x) => x.id === e.contactId);
      if (s && c)
        for (; "active" === e.status && e.nextAt <= td; ) {
          const st = s.steps[e.step];
          if (!st) {
            e.status = "completed";
            break;
          }
          "email" === st.type
            ? c.touches.push({
                id: uid("tc"),
                at: e.nextAt,
                kind: "email",
                direction: "out",
                title: `Sequence email — ${st.subject || s.name}`,
                body: (st.body || "").replace(/\{\{contact\.firstname\}\}/g, c.first || ""),
                by: "Sequence",
              })
            : DB.hub.tasks.some((t) => t.seqStep === st.id && t.contactId === c.id) ||
              DB.hub.tasks.push({
                id: uid("tk"),
                created: td,
                completed: !1,
                title:
                  st.title ||
                  st.subject ||
                  `${(HB_STEP_TYPES.find((t) => t[0] === st.type) || [])[1]} — ${hbName("contact", c)}`,
                type:
                  "call" === st.type
                    ? "Call"
                    : "emailtask" === st.type
                      ? "Email"
                      : "linkedin" === st.type
                        ? "LinkedIn"
                        : "To-do",
                priority: "None" === st.priority ? "" : st.priority || "",
                queue: s.name,
                assignee: c.owner || hbMe(),
                due: e.nextAt,
                time: "08:00",
                notes: st.body || "",
                contactId: c.id,
                dealId: (c.dealIds || [])[0] || "",
                seqStep: st.id,
              }),
            e.step++;
          const nx = s.steps[e.step];
          if (!nx) {
            e.status = "completed";
            break;
          }
          if (((e.nextAt = iso(addDays(e.nextAt, Math.max(0, nx.delay || 0)))), e.nextAt > td)) break;
        }
      else e.status = "unenrolled";
    });
}
