function hbPeriod() {
  const td = today(),
    x = new Date(td + "T00:00:00");
  if ("month" === hbFcPeriod)
    return [
      td.slice(0, 7) + "-01",
      hbEndOfMonth(td),
      x.toLocaleString("en-US", { month: "long", year: "numeric" }),
    ];
  if ("nextmonth" === hbFcPeriod) {
    const y = new Date(x.getFullYear(), x.getMonth() + 1, 1);
    return [iso(y), hbEndOfMonth(iso(y)), y.toLocaleString("en-US", { month: "long", year: "numeric" })];
  }
  let q = Math.floor(x.getMonth() / 3),
    yr = x.getFullYear();
  return (
    "nextquarter" === hbFcPeriod && (q++, q > 3 && ((q = 0), yr++)),
    [iso(new Date(yr, 3 * q, 1)), iso(new Date(yr, 3 * q + 3, 0)), `Q${q + 1} ${yr}`]
  );
}
