  if (!p) return [];
  const texts = [
      m.summary,
      ...(m.sections || []).map((x) => x.text),
      ...(m.details || []).map((x) => x.text),
      ...(m.steps || []).map((x) => x.detail),
    ]
      .filter(Boolean)
      .join("\n"),
    skip = /^(the )?(schedule|plan|plans|project schedule|next steps?|meeting|notes?)$/i,
    seen = new Map();
