function csScore(f, words) {
  const hay = `${f.t} ${f.src || ""} ${f.who || ""} ${f.note || ""} ${f.k}`.toLowerCase();
  let s = 0;
  return (
    words.forEach((w) => {
      w &&
        (hay.includes(w) && (s += 3),
        String(f.t).toLowerCase().includes(w) && (s += 4),
        String(f.who || "")
          .toLowerCase()
          .includes(w) && (s += 2));
    }),
    s
  );
}
