      _id: r.id,
      _module: "Bills & Payroll",
      _label: `Payroll ${r.period || r.id}`,
      _go: eqGo("ap"),
      period: r.period || "",
      from: r.from || "",
      to: r.to || "",
      payDate: r.payDate || "",
      due: due,
      status: r.status || "",
      amount: r2(+r.total || 0),
      gross: r2(+r.gross || 0),
      taxes: r2(+r.taxes || 0),
      employees: +r.employees || 0,
      jobAmount: job,
      overheadAmount: r2((+r.total || 0) - job),
      jobShare: r.total ? Math.round((job / r.total) * 100) : 0,
      approved: FIN_RUN_POSTED.includes(r.status),
      paid: ["paid", "verified"].includes(r.status),
      recognised: FIN_RUN_POSTED.includes(r.status),
      overdue: !FIN_RUN_DONE.includes(r.status) && !!due && due < today(),
      entity: glEntName(r.entityId || "ent1"),
      projects: (r.alloc || [])
        .filter((a) => a.projectId)
