      _label: `Financials · ${label}`,
      _go: eqGo("reports", { tab: "company" }),
      period: label,
      from: from || "",
      to: to,
      income: P.income,
      invoiced: P.invoiced,
      wipAdjustment: P.wipAdj,
      collected: P.collected,
      cogs: P.cogsT,
      overhead: P.ohT,
      gross: P.gross,
      grossMargin: P.grossPct,
      net: P.net,
      netMargin: P.netPct,
      overheadPctOfCost: P.cogsT ? r2((P.ohT / P.cogsT) * 100) : 0,
      payroll: P.payroll,
