        id: id,
        threadId: (body.message || {}).threadId || `dwt_${uid}_${id}`,
        labelIds: ["DRAFT"],
        internalDate: now,
        historyId: ++W.historyId,
        headers: { From: dwAddr(uid), To: r.to, Cc: r.cc, Subject: r.subject, Date: new Date(now).toUTCString() },
        body: r.body,
        attachments: [],
